window.ScripturaLexicons.BDAG_PART_0231 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0231-01\" data-source=\"BDAG\" data-search=\"Μεννά, ὁ nome próprio masculino Mená; ancestral de Jesus BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Μεννά, ὁ</td><td>nome próprio masculino</td><td>Mená; ancestral de Jesus</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0231-02\" data-source=\"BDAG\" data-search=\"μενοῦν partícula antes; pelo contrário; de fato BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μενοῦν</td><td>partícula</td><td>antes; pelo contrário; de fato</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0231-03\" data-source=\"BDAG\" data-search=\"μέντοι partícula realmente; embora; contudo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μέντοι</td><td>partícula</td><td>realmente; embora; contudo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0231-04\" data-source=\"BDAG\" data-search=\"μένω verbo permanecer; morar; persistir; esperar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μένω</td><td>verbo</td><td>permanecer; morar; persistir; esperar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0231-05\" data-source=\"BDAG\" data-search=\"μερίζω verbo dividir; separar; repartir; atribuir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μερίζω</td><td>verbo</td><td>dividir; separar; repartir; atribuir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0231-06\" data-source=\"BDAG\" data-search=\"μέριμνα, ης, ἡ substantivo feminino ansiedade; preocupação; cuidado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μέριμνα, ης, ἡ</td><td>substantivo feminino</td><td>ansiedade; preocupação; cuidado</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0231-07\" data-source=\"BDAG\" data-search=\"μεριμνάω verbo preocupar-se; cuidar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μεριμνάω</td><td>verbo</td><td>preocupar-se; cuidar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0231-08\" data-source=\"BDAG\" data-search=\"μερίς, ίδος, ἡ substantivo feminino parte; porção; distrito; quinhão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μερίς, ίδος, ἡ</td><td>substantivo feminino</td><td>parte; porção; distrito; quinhão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0231-09\" data-source=\"BDAG\" data-search=\"μερισμός, οῦ, ὁ substantivo masculino divisão; distribuição BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μερισμός, οῦ, ὁ</td><td>substantivo masculino</td><td>divisão; distribuição</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0231-10\" data-source=\"BDAG\" data-search=\"μεριστής, οῦ, ὁ substantivo masculino repartidor; árbitro BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μεριστής, οῦ, ὁ</td><td>substantivo masculino</td><td>repartidor; árbitro</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0231-11\" data-source=\"BDAG\" data-search=\"μέρος, ους, τό substantivo neutro parte; região; assunto; participação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μέρος, ους, τό</td><td>substantivo neutro</td><td>parte; região; assunto; participação</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0231-12\" data-source=\"BDAG\" data-search=\"μεσάζω verbo estar no meio ou na metade BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μεσάζω</td><td>verbo</td><td>estar no meio ou na metade</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0231-13\" data-source=\"BDAG\" data-search=\"μεσημβρία, ας, ἡ substantivo feminino meio-dia; sul BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μεσημβρία, ας, ἡ</td><td>substantivo feminino</td><td>meio-dia; sul</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0231-14\" data-source=\"BDAG\" data-search=\"μεσιτεύω verbo mediar; garantir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μεσιτεύω</td><td>verbo</td><td>mediar; garantir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0231-15\" data-source=\"BDAG\" data-search=\"μεσίτης, ου, ὁ substantivo masculino mediador; árbitro BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μεσίτης, ου, ὁ</td><td>substantivo masculino</td><td>mediador; árbitro</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0231-16\" data-source=\"BDAG\" data-search=\"μεσονύκτιον, ου, τό substantivo neutro meia-noite BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μεσονύκτιον, ου, τό</td><td>substantivo neutro</td><td>meia-noite</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0231-17\" data-source=\"BDAG\" data-search=\"Μεσοποταμία, ας, ἡ nome geográfico feminino Mesopotâmia BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Μεσοποταμία, ας, ἡ</td><td>nome geográfico feminino</td><td>Mesopotâmia</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0231-18\" data-source=\"BDAG\" data-search=\"μέσος, η, ον adjetivo central; no meio; entre BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μέσος, η, ον</td><td>adjetivo</td><td>central; no meio; entre</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0231-19\" data-source=\"BDAG\" data-search=\"μεσότοιχον, ου, τό substantivo neutro parede divisória BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μεσότοιχον, ου, τό</td><td>substantivo neutro</td><td>parede divisória</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0231-20\" data-source=\"BDAG\" data-search=\"μεσουράνημα, ατος, τό substantivo neutro zênite; meio do céu BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μεσουράνημα, ατος, τό</td><td>substantivo neutro</td><td>zênite; meio do céu</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0231-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μεννά, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Μεννά</span>, <span class=\"greek\">ὁ</span>, indeclinável (numa série de nomes indeclináveis, dificilmente <span class=\"greek\">Μεννᾶ</span> seria genitivo de <span class=\"greek\">Μεννᾶς</span>), Mená, na genealogia de Jesus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.31\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:31</a> (<span class=\"greek\">Μαινάν</span>, variante textual).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0231-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μενοῦν</h1><div class=\"entry-meta\"><span>partícula</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μενοῦν</span> (também <span class=\"greek\">μὲν</span> <span class=\"greek\">οὖν</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.28\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:28</a> (para a forma negativa, ver <span class=\"greek\">οὐ</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">οὖν</span>) e <span class=\"greek\">μενοῦνγε</span> (também <span class=\"greek\">μενοῦν</span> <span class=\"greek\">γε</span>), partículas empregadas especialmente em respostas, para enfatizar ou corrigir (B-D-F §450, 4; Rob. 1151s.), até mesmo — contrariamente ao uso do grego antigo — no começo de uma oração (Phryn. 342 Lob. [322 R.]): antes, pelo contrário (Soph., Aj. 1363; Pla., Crito 44b; X., Cyr. 8, 3, 37) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.28\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:28</a>, variante textual. De fato <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 10:18</a>. <span class=\"greek\">ἀλλὰ</span> <span class=\"greek\">μενοῦνγε</span>, mais que isso <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 3:8</a>. <span class=\"greek\">μενοῦνγε</span> <span class=\"greek\">σὺ</span> <span class=\"greek\">τίς</span> <span class=\"greek\">εἶ</span> … ;, pelo contrário, quem és tu … ? (ou: quem pensas que és para [questionar Deus]?) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:20</a>.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0231-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μέντοι</h1><div class=\"entry-meta\"><span>partícula</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μέντοι</span>, partícula (Trag., Hdt. e posteriores; inscrições, papiros, LXX; TestSol 11:9 C; TestJob; Jos., Ant. 14, 162, C. Ap. 1, 8; 13 e outros.—Denniston 397–412).</p><p class=\"entry-text\">① Realmente, efetivamente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:8</a>.</p><p class=\"entry-text\">② Predominantemente adversativa (cf. <span class=\"greek\">οὐ</span> <span class=\"greek\">μέντοι</span> <span class=\"greek\">γε</span>, “embora não”, Just., D. 5, 1): embora, certamente, de fato; <span class=\"greek\">οὐδεὶς</span> <span class=\"greek\">μ</span>. <span class=\"greek\">εἶπεν</span>, embora ninguém tenha dito <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.27\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:27</a>; cf. 7:13. <span class=\"greek\">οὐ</span> <span class=\"greek\">μ</span>., embora não, certamente não 20:5; 21:4; Hs 6, 1, 6, variante textual; Papias (2:15). <span class=\"greek\">ὁ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">θεμέλιος</span> <span class=\"greek\">ἕστηκεν</span>, contudo, o firme fundamento permanece <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:19</a>. <span class=\"greek\">ὅμως</span> <span class=\"greek\">μ</span>., ainda assim, apesar disso (Kühner-G. II 280) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.42\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:42</a>.—Com sentido enfraquecido, simplesmente mas Jd 8 (B-D-F §450, 1; Rob. 1154; 1188).—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0231-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μένω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μένω</span> (Hom. e posteriores), imperfeito <span class=\"greek\">ἔμενον</span>; futuro <span class=\"greek\">μενῶ</span>; 1º aoristo <span class=\"greek\">ἔμεινα</span>, imperativo <span class=\"greek\">μεῖνον</span> (Hv 3, 1, 9); particípio perfeito, plural <span class=\"greek\">μεμενηκότας</span> 2 Macc 8:1; mais-que-perfeito <span class=\"greek\">μεμενήκειν</span> 1J 2:19 (sobre a ausência de aumento, ver B-D-F §66, 1; W-S. §12, 4; Mlt-H. 190).</p><p class=\"entry-text\">① Permanecer, ficar, intransitivo.</p><p class=\"entry-text\">ⓐ Uma pessoa ou coisa permanece onde está.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. Acerca de um lugar: ficar, frequentemente no sentido específico de morar, habitar, alojar-se (Horapollo 2, 49 <span class=\"greek\">μ</span>. alternando com <span class=\"greek\">οἰκέω</span>), com <span class=\"greek\">ἐν</span> e dativo (Ps.-Demosth. 43, 75 <span class=\"greek\">μ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">οἴκοις</span>; Vi. Aesopi G 12 p. 259, 6 P.): <span class=\"greek\">ἐν</span> <span class=\"greek\">οἰκίᾳ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:27</a>; <span class=\"greek\">ἐν</span> <span class=\"greek\">αὐτῇ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">οἰκίᾳ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.35\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:35a</a>; <span class=\"greek\">ἐν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">οἴκῳ</span> <span class=\"greek\">σου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 19:5</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πλοίῳ</span>, permanecer no navio <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.31\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:31</a>. <span class=\"greek\">μ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">Γαλιλαίᾳ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.9\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:9</a>.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.43\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:43</a>; 20:15, variante textual; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.20\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 4:20</a>. <span class=\"greek\">κατὰ</span> <span class=\"greek\">πόλιν</span>, permanecer na cidade MPol 5:1 (Just., A I, 67, 3). Com advérbio de lugar: <span class=\"greek\">ἐκεῖ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:12</a>; 10:40; 11:54 (ver <span class=\"greek\">διατρίβω</span>); Hs 9, 11, 7. <span class=\"greek\">ὧδε</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.38\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:38</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:34</a>; Hs 9, 11, 1. <span class=\"greek\">ποῦ</span> <span class=\"greek\">μένεις</span>;, onde moras? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.38\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:38</a>; cf. v. 39 (Sb 2639 <span class=\"greek\">ποῦ</span> <span class=\"greek\">μένι</span> <span class=\"greek\">Θερμοῦθις</span>; Pel.-Leg. 7, 27; Nicetas Eugen. 1, 230 H. <span class=\"greek\">ποῦ</span> <span class=\"greek\">μένεις</span>;). Com acusativo de duração (Demetr.: 722 Fgm. 1, 11 Jac.; JosAs 20:8; Jos., Ant. 1, 299) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.39\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:39b</a>; 4:40b; 11:6; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 21:7</a>; D 11:5; 12:2. Com indicações temporais de outro tipo: <span class=\"greek\">ἕως</span> <span class=\"greek\">ἂν</span> <span class=\"greek\">ἐξέλθητε</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:11</a>. <span class=\"greek\">ὡς</span> <span class=\"greek\">μῆνας</span> <span class=\"greek\">τρεῖς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.56\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:56</a>. <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">αἰῶνα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.35\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:35b</a>. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">πλείονα</span> <span class=\"greek\">χρόνον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:20</a>. Com preposição: <span class=\"greek\">παρά</span> <span class=\"greek\">τινι</span> <span class=\"greek\">μ</span>., hospedar-se com alguém (Cebes 9, 2; Jos., Ant. 20, 54) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.39\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:39b</a>; 4:40a; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:3</a> (morar com também é provável: Lucian, Timon 10); 21:7, 8. <span class=\"greek\">παρ</span>’ <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">μένων</span>, quando eu estava (permanecendo) convosco <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.14.25\" target=\"_blank\" rel=\"noopener noreferrer\">J 14:25</a>. <span class=\"greek\">πρός</span> <span class=\"greek\">τινα</span>, com alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:3</a> D; D 12:2. <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινα</span>, permanecer sobre alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.32\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:32</a>s. <span class=\"greek\">σύν</span> <span class=\"greek\">τινι</span>, com alguém (4 Macc 18:9) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.56\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:56</a>; 24:29b. Também <span class=\"greek\">μ</span>. <span class=\"greek\">μετά</span> <span class=\"greek\">τινος</span> (Gen 24:55) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.29\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:29a</a>; Hs 9, 11, 1; 3; 6; 7. <span class=\"greek\">καθ</span>’ <span class=\"greek\">ἑαυτόν</span>, morar sozinho, em alojamento próprio <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:16</a> (da denominada, em latim, custodia libera; ver BAFCS III 276, 364s.; 384s.). De um cadáver: <span class=\"greek\">μ</span>. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">σταυροῦ</span>, permanecer (suspenso) na cruz <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.31\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:31</a>. De um ramo: <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἀμπέλῳ</span>, permanecer na videira, isto é, não ser cortado 15:4b. De pedras: <span class=\"greek\">μ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ὁδῷ</span>, permanecer no caminho Hv 3, 2, 9. De pedras que permanecem na construção divina e não são removidas Hs 9, 13, 4; 9. Também em linguagem figurada: <span class=\"greek\">τὸ</span> <span class=\"greek\">κάλυμμα</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἀναγνώσει</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">παλαιᾶς</span> <span class=\"greek\">διαθήκης</span> <span class=\"greek\">μένει</span>, o véu permanece sem ser retirado na leitura do AT (impedindo sua compreensão correta) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 3:14</a>. Em emprego absoluto <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:15</a>.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Em sentido transferido, acerca de alguém que não abandona determinado domínio ou esfera: permanecer, continuar, habitar (Pla., Ep. 10, 358c <span class=\"greek\">μένε</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἤθεσιν</span>, <span class=\"greek\">οἷσπερ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">νῦν</span> <span class=\"greek\">μένεις</span>; Alex. Aphr., An. II 1 p. 2, 15 <span class=\"greek\">μ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">ἀπορίαις</span>=permanecer dominado por dúvidas; Jos., Ant. 4, 185; TestJos. 1:3 <span class=\"greek\">ἐν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἀληθείᾳ</span>; Just., D. 8, 3 <span class=\"greek\">ἐν</span> … <span class=\"greek\">τῷ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">φιλοσωφίας</span> <span class=\"greek\">τρόπῳ</span>): <span class=\"greek\">ἐν</span> <span class=\"greek\">ἁγνείᾳ</span> IPol 5:2; cf. IEph 10:3. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">διδαχῇ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Χριστοῦ</span>, permanecer na doutrina de Cristo 2J 9a; cf. v. 9b (2 Macc 8:1 <span class=\"greek\">μ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">Ἰουδαϊσμῷ</span>). <span class=\"greek\">ἐν</span> <span class=\"greek\">πίστει</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀγάπῃ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 2:15</a>. <span class=\"greek\">μένε</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">οἷς</span> <span class=\"greek\">ἔμαθες</span>, permanece no que aprendeste <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 3:14</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">λόγῳ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ἐμῷ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.31\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:31</a>. <span class=\"greek\">μείνατε</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἀγάπῃ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἐμῇ</span>, permanecei no meu amor 15:9s.; cf. 1J 4:16. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">φωτί</span> 2:10. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θανάτῳ</span> 3:14. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">σκοτίᾳ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.46\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:46</a>. Sem <span class=\"greek\">ἐν</span> AcPlCor 2:36. A expressão <span class=\"greek\">μ</span>. <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span> é especialmente frequente em J para denotar uma comunhão interior, pessoal e duradoura. Assim, de Deus em sua relação com Cristo: <span class=\"greek\">ὁ</span> <span class=\"greek\">πατὴρ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἐμοὶ</span> <span class=\"greek\">μένων</span>, o Pai, que permanece em mim <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.14.10\" target=\"_blank\" rel=\"noopener noreferrer\">J 14:10</a>. Dos cristãos em sua relação com Cristo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.56\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:56</a>; 15:4ac, 5–7; 1J 2:6, 24c. De Cristo em sua relação com os cristãos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.15.4\" target=\"_blank\" rel=\"noopener noreferrer\">J 15:4a</a>, 5 (Goodsp., Probs. 112–15). Dos cristãos em sua relação com Deus 1J 2:24c, 27s.; 3:6, 24a; 4:13. De Deus em relação com os cristãos 1J 3:24; 4:12s., 15.—Inversamente, de algo que permanece em alguém, igualmente no uso joanino: da palavra de Deus 1J 2:14; das palavras de Cristo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.15.7\" target=\"_blank\" rel=\"noopener noreferrer\">J 15:7b</a>; cf. 1J 2:24ab; da unção celestial v. 27; do amor de Deus 1J 3:17; da semente de Deus 3:9; da verdade 2J 2. A permanência da posse é demonstrada pela expressão <span class=\"greek\">ἔχειν</span> <span class=\"greek\">τι</span> <span class=\"greek\">μένον</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἑαυτῷ</span>, ter algo continuamente, permanentemente 1J 3:15; a palavra de Deus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.38\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:38</a>. Em lugar de <span class=\"greek\">μ</span>. <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span>, também <span class=\"greek\">μ</span>. <span class=\"greek\">παρά</span> <span class=\"greek\">τινι</span>, permanecer com alguém: do Espírito da verdade <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.14.17\" target=\"_blank\" rel=\"noopener noreferrer\">J 14:17</a>. Também da ira de Deus: <span class=\"greek\">μένει</span> <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">αὐτόν</span>, permanece sobre ele 3:36.—GPercorara, De verbo ‘manere’ ap. Jo.: Div. Thomas Piac. 40, ’37, 159–71.</p><p class=\"entry-text\">ⓑ Uma pessoa ou coisa continua no mesmo estado (ParJer 7:37 <span class=\"greek\">ἔμεινε</span> <span class=\"greek\">διδάσκων</span>; ApcSed 11:13 <span class=\"greek\">ἀκίνητοι</span> <span class=\"greek\">μένετε</span>; Just., D. 90, e Lucian, Laps. 16 <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">τάξει</span> <span class=\"greek\">μ</span>.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.20\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:20</a>, 24. <span class=\"greek\">μένει</span> <span class=\"greek\">ἱερεὺς</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">διηνεκές</span>, ele permanece sacerdote para sempre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.3\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:3</a>. <span class=\"greek\">αὐτὸς</span> <span class=\"greek\">μόνος</span> <span class=\"greek\">μένει</span>, permanece sozinho <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.24\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:24</a>. <span class=\"greek\">μενέτω</span> <span class=\"greek\">ἄγαμος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:11</a>. <span class=\"greek\">ἀσάλευτος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.41\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:41</a>. <span class=\"greek\">πιστός</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:13</a>. <span class=\"greek\">ἀόρατος</span> Dg 6:4. (<span class=\"greek\">μ</span>̣<span class=\"greek\">ε</span>̣<span class=\"greek\">ί</span>̣<span class=\"greek\">νατε</span> <span class=\"greek\">νικηταί</span>· <span class=\"greek\">μεί</span>̣<span class=\"greek\">ν</span>̣[<span class=\"greek\">α</span>]<span class=\"greek\">τ</span>̣<span class=\"greek\">ε</span> Ox 1602, 30s. é leitura equivocada; interpretação diferente AcPl Ha 8, 22//BMM recto 28=HTR 31, 79 n. 2, linha 10; ver CSchmidt, nota marginal sobre AcPl Ha 8, 22 [<span class=\"greek\">μ</span>]<span class=\"greek\">ε</span>̣<span class=\"greek\">γ</span>̣<span class=\"greek\">α</span>̣<span class=\"greek\">ς</span> <span class=\"greek\">ἐπ</span>̣<span class=\"greek\">ίκειται</span> <span class=\"greek\">πιρασμός</span>; Borger GGA 137). <span class=\"greek\">ἀσκανδάλιστος</span> <span class=\"greek\">μείνῃ</span> <span class=\"greek\">ἡ</span> … <span class=\"greek\">ἐκκλησία</span> AcPlCor 1:16. <span class=\"greek\">μ</span>. <span class=\"greek\">μετά</span> <span class=\"greek\">τινος</span>, permanecer em comunhão com alguém 1J 2:19. De quem se divorciou da esposa: ficar sozinho, permanecer sem casar Hm 4, 1, 6; 10; 4, 4, 2. <span class=\"greek\">οὐχὶ</span> <span class=\"greek\">μένον</span> <span class=\"greek\">σοὶ</span> <span class=\"greek\">ἔμενεν</span>;, não era (o terreno) teu enquanto permanecia (sem ser vendido)? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:4</a> (cf. 1 Macc 15:7 e ver OHoltzmann, ZKG 14, 1893, 327–36).—Com advérbio (Just., A I, 29, 3, D. 58, 3 <span class=\"greek\">βεβαίως</span>): <span class=\"greek\">οὕτως</span> <span class=\"greek\">μ</span>., permanecer como se está (isto é, sem casar) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.40\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:40</a>. <span class=\"greek\">ἁγνῶς</span> 2:3. <span class=\"greek\">μ</span>. <span class=\"greek\">ὡς</span> <span class=\"greek\">ἐγώ</span>, permanecer como eu estou <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:8</a>.</p><p class=\"entry-text\">② Continuar existindo: permanecer, durar, persistir, continuar vivo, intransitivo.</p><p class=\"entry-text\">ⓐ De pessoas (Ps 9:8 <span class=\"greek\">ὁ</span> <span class=\"greek\">κύριος</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">αἰῶνα</span> <span class=\"greek\">μ</span>.; 101:13; Da 6:27; Just., D. 128, 4 <span class=\"greek\">ἄγγελοι</span> … <span class=\"greek\">ἀεὶ</span> <span class=\"greek\">μένοντες</span>): <span class=\"greek\">ὁ</span> <span class=\"greek\">Χριστὸς</span> <span class=\"greek\">μ</span>. <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">αἰῶνα</span>, Cristo permanece (aqui) para sempre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.34\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:34</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.24\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:24</a>; 1J 2:17. De Deus AcPl Ha 2, 28; 9, 11. Em sentido pleno: permanecer vivo, estar vivo (Epict. 3, 24, 97; Diog. L. 7, 174; Achilles Tat. 8, 10. <span class=\"greek\">μένειν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ζῆν</span> Plut., Mor. 1042d; Eccl 7:15; Just., A I, 63, 17) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.21.22\" target=\"_blank\" rel=\"noopener noreferrer\">J 21:22</a>s.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.25\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.17.10\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 17:10</a>.</p><p class=\"entry-text\">ⓑ De coisas (Maximus Tyr. 4, 8b e Polyaenus 7, 34: <span class=\"greek\">γῆ</span> <span class=\"greek\">μένει</span>; Socrat., Ep. 31 [=33]; Hierocles 15, 454 <span class=\"greek\">ὁ</span> <span class=\"greek\">πόνος</span> <span class=\"greek\">παρῆλθεν</span>, <span class=\"greek\">τὸ</span> <span class=\"greek\">καλὸν</span> <span class=\"greek\">μένει</span>; Just., A I, 18, 2 <span class=\"greek\">αἴσθησις</span> … <span class=\"greek\">μένει</span>; Ath. 19, 2 <span class=\"greek\">μένει</span> <span class=\"greek\">σύστασις</span>): de uma cidade, <span class=\"greek\">ἔμεινεν</span> <span class=\"greek\">ἂν</span> <span class=\"greek\">μέχρι</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">σήμερον</span>, teria subsistido até hoje <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:23</a>. <span class=\"greek\">μένουσα</span> <span class=\"greek\">πόλις</span>, cidade permanente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.14\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:14</a>.—<span class=\"greek\">ἡ</span> <span class=\"greek\">φιλαδελφία</span> <span class=\"greek\">μενέτω</span>, que o amor fraterno continue 13:1 (JCambier, Salesianum 11, ’49, 62–96).—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.41\" target=\"_blank\" rel=\"noopener noreferrer\">J 9:41</a>; 15:16. <span class=\"greek\">εἰ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἔργον</span> <span class=\"greek\">μενεῖ</span>, se a obra subsistir <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 3:14</a>. <span class=\"greek\">ὕπαρξις</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.34\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:34</a>. <span class=\"greek\">δικαιοσύνη</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.9.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 9:9</a> (Ps 111:9). <span class=\"greek\">ἡ</span> <span class=\"greek\">κατ</span>’ <span class=\"greek\">ἐκλογὴν</span> <span class=\"greek\">πρόθεσις</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:11</a> (sobre o desígnio de Deus Ps 32:11). <span class=\"greek\">λόγος</span> <span class=\"greek\">θεοῦ</span>, a palavra de Deus perdura <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.23\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:23</a> (Just., D. 61, 2; cf. 1 Esdr 4:38 <span class=\"greek\">ἡ</span> <span class=\"greek\">ἀλήθεια</span> <span class=\"greek\">μένει</span>). <span class=\"greek\">τ</span>. <span class=\"greek\">ῥῆμα</span> <span class=\"greek\">κυρίου</span> <span class=\"greek\">μένει</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">αἰῶνα</span> v. 25 (Is 40:8). <span class=\"greek\">ἡ</span> <span class=\"greek\">βρῶσις</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">μένουσα</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ζωὴν</span> <span class=\"greek\">αἰώνιον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.27\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:27</a>. <span class=\"greek\">τὴν</span> <span class=\"greek\">δύναμιν</span> <span class=\"greek\">σου</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">μένουσαν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.7\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 11:7</a>, variante textual. <span class=\"greek\">ζώσης</span> <span class=\"greek\">φωνῆς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μενούσης</span> Papias (2:4). <span class=\"greek\">τὸ</span> <span class=\"greek\">μένον</span>, o que é permanente (Philo, Leg. All. 3, 100.—Oposto a <span class=\"greek\">τὸ</span> <span class=\"greek\">καταργούμενον</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 3:11</a>. <span class=\"greek\">μένει</span> <span class=\"greek\">πίστις</span>, <span class=\"greek\">ἐλπὶς</span>, <span class=\"greek\">ἀγάπη</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.13.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 13:13</a> (WMarxsen, D. ‘Bleiben’ im <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.13.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 13:13</a>, OCullmann Festschr., ’72, 223–29; sobre a escatologia, cf. En 97:6–10 e ver bibliografia de <span class=\"greek\">ἀγάπη</span> 1a.—Sobre o contraste <span class=\"greek\">πίπτει</span> [v. 8]—<span class=\"greek\">μένει</span>, cf. Pla., Crat. 44, 440a <span class=\"greek\">εἰ</span> <span class=\"greek\">μεταπίπτει</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">χρήματα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μηδὲν</span> <span class=\"greek\">μένει</span>). Oposto a <span class=\"greek\">σαλευόμενα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.27\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:27</a>.</p><p class=\"entry-text\">③ Esperar, aguardar, transitivo.</p><p class=\"entry-text\">ⓐ De pessoas: esperar alguém que está chegando (Hom.; Thu. 4, 124, 4; X., An. 4, 4, 20; Pla., Leg. 8, 833c; Polyb. 4, 8, 4; Tob 2:2 BA; 2 Macc 7:30; TestJob 11:1; Jos., Ant. 13, 19), <span class=\"greek\">τινά</span>, com indicação do lugar: <span class=\"greek\">ἔμενον</span> <span class=\"greek\">ἡμᾶς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">Τρῳάδι</span>, estavam à nossa espera em Trôade <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:5</a>.</p><p class=\"entry-text\">ⓑ De coisas, como perigos ou desgraças que aguardam ou ameaçam alguém (Trag.; Kaibel 654, 9 <span class=\"greek\">κἀμὲ</span> <span class=\"greek\">μένει</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">θανεῖν</span>; SibOr 4, 114, variante textual <span class=\"greek\">σὲ</span>): <span class=\"greek\">θλίψεις</span> <span class=\"greek\">με</span> <span class=\"greek\">μένουσιν</span>, aflições me aguardam <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:23</a>.—Das 118 ocorrências de <span class=\"greek\">μένω</span> no NT, 67 encontram-se nos escritos joaninos (40 no evangelho; 24 em 1J; 3 em 2J).—JHeise, Bleiben: Menein in d. Johan. Schr., ’67; FHauck, TW IV 578–93: <span class=\"greek\">μένω</span> e palavras relacionadas.—B. 836. DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0231-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μερίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μερίζω</span> (<span class=\"greek\">μέρος</span>), futuro ático <span class=\"greek\">μεριῶ</span> 1 Cl 16:13; LXX; 1º aoristo <span class=\"greek\">ἐμέρισα</span>; perfeito <span class=\"greek\">μεμέρικα</span>; infinitivo do 1º aoristo médio <span class=\"greek\">μερίσασθαι</span>. Passivo: 1º futuro <span class=\"greek\">μερισθήσομαι</span> LXX; 1º aoristo <span class=\"greek\">ἐμερίσθην</span>; perfeito <span class=\"greek\">μεμέρισμαι</span> (“dividir, separar”, X. e posteriores).</p><p class=\"entry-text\">① Separar em partes, dividir.</p><p class=\"entry-text\">ⓐ De uma quantia de dinheiro, na voz média: <span class=\"greek\">μερίζεσθαί</span> <span class=\"greek\">τι</span> <span class=\"greek\">μετά</span> <span class=\"greek\">τινος</span>, compartilhar alguma coisa com alguém (Demosth. 34, 18; cf. Jos., Ant. 1, 169 <span class=\"greek\">τὶ</span> <span class=\"greek\">πρός</span> <span class=\"greek\">τινα</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:13</a>.</p><p class=\"entry-text\">ⓑ De pessoas ou situações, na voz ativa e passiva, em sentido transferido.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. Dividir (Mel., P. 56, 407 <span class=\"greek\">ἄνθρωπος</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θανάτου</span> <span class=\"greek\">μεριζόμενος</span>; Tat. 26, 2 <span class=\"greek\">μερίζοντες</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">σοφίαν</span>; Procop. Soph., Ep. 17 <span class=\"greek\">ψυχὴ</span> <span class=\"greek\">μεριζομένη</span>): <span class=\"greek\">μεμέρισται</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">Χριστός</span>;, acaso Cristo foi dividido? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:13</a> (GWhitaker, Chrysostom on <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:13</a>: JTS 15, 1914, 254–57). Dividir <span class=\"greek\">ὑμᾶς</span> IMg 6:2. <span class=\"greek\">βασιλεία</span>, <span class=\"greek\">πόλις</span>, <span class=\"greek\">οἰκία</span> <span class=\"greek\">μερισθεῖσα</span> <span class=\"greek\">καθ</span>’ <span class=\"greek\">ἑαυτῆς</span>, reino, cidade ou família dividida contra si mesma, em desunião <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:25</a>. <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">ἑαυτὸν</span> <span class=\"greek\">ἐμερίσθη</span>, ficou dividido contra si mesmo v. 26; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:24</a>–26. Em emprego absoluto, <span class=\"greek\">ὁ</span> <span class=\"greek\">γαμήσας</span> <span class=\"greek\">μεμέρισται</span>, o homem casado (isto é, sua atenção) está dividido, pois procura agradar simultaneamente ao Senhor e à esposa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.34\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:34</a>.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Retirar uma parte (do todo), separar: <span class=\"greek\">μερίσας</span> … <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πνεύματος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">χριστοῦ</span> <span class=\"greek\">ἔπεμψεν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">προφήτας</span>, (Deus) tomou uma porção do espírito de Cristo e a enviou aos profetas AcPlCor 2:10.</p><p class=\"entry-text\">② Fazer uma distribuição.</p><p class=\"entry-text\">ⓐ Distribuir <span class=\"greek\">τί</span> <span class=\"greek\">τισιν</span>, alguma coisa a algumas pessoas (PTebt 302, 12; POxy 713, 29; Pr 19:14; Just., D. 104, 2 <span class=\"greek\">ἐμέρισαν</span> <span class=\"greek\">ἑαυτοῖς</span> … <span class=\"greek\">τὰ</span> <span class=\"greek\">ἱμάτια</span>; cf. A I, 35, 8 <span class=\"greek\">ἐμερίσαντο</span> <span class=\"greek\">ἑαυτοῖς</span> [<span class=\"greek\">διεμερίσαντο</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:35</a>]): <span class=\"greek\">τοὺς</span> <span class=\"greek\">δύο</span> <span class=\"greek\">ἰχθύας</span> <span class=\"greek\">πᾶσιν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.41\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:41</a>. Sem dativo: <span class=\"greek\">τῶν</span> <span class=\"greek\">ἰσχυρῶν</span> <span class=\"greek\">μεριεῖ</span> <span class=\"greek\">σκῦλα</span>, repartirá os despojos dos fortes 1 Cl 16:13 (Is 53:12).</p><p class=\"entry-text\">ⓑ Distribuir, atribuir, repartir <span class=\"greek\">τί</span> <span class=\"greek\">τινι</span>, algo a alguém (Polyb. 11, 28, 9; Diod S 13, 22, 8 <span class=\"greek\">μ</span>. <span class=\"greek\">τινὶ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ἔλεον</span>; UPZ 19, 20 [163 a.C.]; 146, 38; Sb 8139, 19s. [inscrição do século I a.C., sobre Ísis] <span class=\"greek\">πᾶσι</span> <span class=\"greek\">μερίζεις</span>, <span class=\"greek\">οἷσι</span> <span class=\"greek\">θέλεις</span>, <span class=\"greek\">ζωὴν</span> <span class=\"greek\">παντοδαπῶν</span> <span class=\"greek\">ἀγαθῶν</span>; PGM 13, 635 <span class=\"greek\">μέρισόν</span> <span class=\"greek\">μοι</span> <span class=\"greek\">ἀγαθά</span>; Sir 45:20; ApcMos 15; EpArist 224 [<span class=\"greek\">θεός</span>]): <span class=\"greek\">ἑκάστῳ</span> <span class=\"greek\">μέτρον</span> <span class=\"greek\">πίστεως</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 12:3</a>. <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">μέτρον</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κανόνος</span> <span class=\"greek\">οὗ</span> <span class=\"greek\">ἐμέρισεν</span> <span class=\"greek\">ἡμῖν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">μέτρου</span>, segundo a medida do limite (ou área) que Deus nos atribuiu <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.10.13\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 10:13</a>. <span class=\"greek\">ᾧ</span> <span class=\"greek\">δεκάτην</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">πάντων</span> <span class=\"greek\">ἐμέρισεν</span> <span class=\"greek\">Ἀβραάμ</span>, àquele a quem Abraão destinou o dízimo de tudo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.2\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:2</a>. Somente com dativo da pessoa (En 27:4): <span class=\"greek\">ἑκάστῳ</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">ἐμέρισεν</span> (variante textual <span class=\"greek\">μεμέρικεν</span>) <span class=\"greek\">ὁ</span> <span class=\"greek\">κύριος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:17</a>.—DELG s.v. <span class=\"greek\">μείρομαι</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0231-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μέριμνα, ης, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μέριμνα</span>, <span class=\"greek\">ης</span>, <span class=\"greek\">ἡ</span> (Hes.; Vett. Val. 131, 3; 6; 271, 3; PGiss 19, 8; 22, 11; EpArist 271; LXX.—Na LXX, o plural ocorre somente em Da 11:26, como em Hes., Op. 178 e outros; PRyl 28, 219), ansiedade, preocupação, cuidado; <span class=\"greek\">πᾶσα</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">ὑμῶν</span>, toda a vossa ansiedade <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.5.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 5:7</a> (Ps 54:23); cf. Hv 3, 11, 3; 4, 2, 4s. Com genitivo objetivo, <span class=\"greek\">μ</span>. <span class=\"greek\">πασῶν</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἐκκλησιῶν</span>, preocupação com todas as igrejas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.28\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:28</a>. <span class=\"greek\">μ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">βίου</span>, as preocupações da vida (caso <span class=\"greek\">τοῦ</span> <span class=\"greek\">β</span>. se ligue a <span class=\"greek\">μ</span>.—UPZ 20, 29 [163 a.C.] <span class=\"greek\">τὴν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">βίου</span> <span class=\"greek\">μέριμναν</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.14\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:14</a>. Também <span class=\"greek\">μ</span>. <span class=\"greek\">βιωτικαί</span> 21:34. <span class=\"greek\">ἡ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">αἰῶνος</span>, a preocupação com o mundo, isto é, a era presente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:22</a> (ver <span class=\"greek\">αἰών</span> 2a); plural <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:19</a>. Ver o verbete seguinte.—B. 1092. DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0231-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεριμνάω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μεριμνάω</span>, futuro <span class=\"greek\">μεριμνήσω</span>; 1º aoristo <span class=\"greek\">ἐμερίμνησα</span> (<span class=\"greek\">μέριμνα</span>; desde Soph., Oed. Rex 1124; X., Pla. e outros; papiros, LXX; ParJer 6:15; EpArist 296; SibOr 3, 222; 234; Just., A I, 25, 2).</p><p class=\"entry-text\">① Estar apreensivo, sentir ansiedade, estar ansioso, preocupar-se (excessivamente) (PTebt 315, 9 [século II d.C.] <span class=\"greek\">γράφω</span> <span class=\"greek\">ὅπως</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">μεριμνῇς</span>; Ps 37:19): <span class=\"greek\">μηδέν</span>, não andar ansioso por coisa alguma <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 4:6</a> (WWeeda, Filipp. 4:6 en 7: TSt 34, 1916, 326–35). <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:28</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:26</a>; Dg 9:6. Seguido de pergunta indireta: <span class=\"greek\">πῶς</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">τί</span> <span class=\"greek\">λαλήσητε</span>, como devereis falar ou o que devereis dizer <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:19</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:11</a> (cf. ParJer 6:15 <span class=\"greek\">τὸ</span> <span class=\"greek\">πῶς</span> <span class=\"greek\">ἀποστείλῃς</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">Ἰερεμίαν</span>). Com dativo e pergunta seguinte: <span class=\"greek\">μὴ</span> <span class=\"greek\">μεριμνᾶτε</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ψυχῇ</span> (dativo de interesse: “por vossa vida”, B-D-F §188, 1; Rob. 539) <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">τί</span> <span class=\"greek\">φάγητε</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:22</a>. Em emprego absoluto <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:31</a>; no particípio (ver Mlt. 230) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:27</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:25</a>. Ao lado de <span class=\"greek\">θορυβάζεσθαι</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">πολλά</span>, acerca das preocupações perturbadoras dos afazeres domésticos 10:41 (o texto é incerto; ver Zahn e EKlostermann, também FSträhl, Krit. u. exeget. Beleuchtung von <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.41\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:41</a>f: SchTZ 4, 1887, 116–23). <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">αὔριον</span>, não vos preocupeis com o amanhã <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:34a</a>.</p><p class=\"entry-text\">② Cuidar, ocupar-se, preocupar-se com <span class=\"greek\">τὶ</span>, alguma coisa (Soph., no local citado; cf. Bar 3:18): <span class=\"greek\">τὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span>, os assuntos do Senhor <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.32\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:32</a>; 34a. <span class=\"greek\">τὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κόσμου</span> vv. 33, 34b. <span class=\"greek\">τὰ</span> <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span>, o bem-estar de alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:20</a>. <span class=\"greek\">ἡ</span> <span class=\"greek\">αὔριον</span> <span class=\"greek\">μεριμνήσει</span> <span class=\"greek\">ἑαυτῆς</span>, o amanhã cuidará de si mesmo (Itala “sibi”.—B-D-F §176, 2; Rob. 509) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:34b</a> (variante textual <span class=\"greek\">τὰ</span> <span class=\"greek\">ἑαυτῆς</span>, cuidar dos próprios assuntos). <span class=\"greek\">τὶ</span> <span class=\"greek\">ὑπέρ</span> <span class=\"greek\">τινος</span>: <span class=\"greek\">ἵνα</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">αὐτὸ</span> <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">ἀλλήλων</span> <span class=\"greek\">μεριμνῶσιν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">μέλη</span>, para que os membros demonstrem igual cuidado uns pelos outros <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.25\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 12:25</a>.—DELG s.v. <span class=\"greek\">μέριμνα</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0231-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μερίς, ίδος, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μερίς</span>, <span class=\"greek\">ίδος</span>, <span class=\"greek\">ἡ</span> (ver <span class=\"greek\">μερίζω</span> e os três verbetes seguintes; Antiphon, Thu. e posteriores; inscrições, papiros, LXX, TestSol; TestJob 38:2; 41:5; Test12Patr; Philo; Jos., Ant. 11, 292, Vi. 36; Just.).</p><p class=\"entry-text\">① Porção de um todo dividido: parte (Pla., Soph. p. 266a; Demetr.: 722 Fgm. 1, 14 Jac.; Diod S 15, 31, 2; 15, 64, 1 [a comparação com 15, 63, 4 <span class=\"greek\">τέτταρα</span> <span class=\"greek\">μέρη</span> … <span class=\"greek\">ἡ</span> <span class=\"greek\">πρώτη</span> <span class=\"greek\">μερίς</span> mostra que não é necessário supor diferença de sentido entre essas formas]. Em inscrições e papiros, frequentemente “distrito”: OGI 177, 9; 179, 8; PPetr III, 32 recto, 3 <span class=\"greek\">τῆς</span> <span class=\"greek\">Θεμίστου</span> <span class=\"greek\">μερίδος</span>; BGU 975, 6 [45 d.C.]; PTebt 302, 4; 315, 13; Diod S 1, 54, 3; Josh 18:6). A redação de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:12</a>, variante textual, ao descrever Filipos, <span class=\"greek\">ἥτις</span> <span class=\"greek\">ἐστὶν</span> <span class=\"greek\">πρώτη</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">μερίδος</span> <span class=\"greek\">Μακεδονίας</span> <span class=\"greek\">πόλις</span> (outras variantes, entre elas <span class=\"greek\">πρ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">μερ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">Μακ</span>.; <span class=\"greek\">πρ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">Μακ</span>.), é difícil por causa de <span class=\"greek\">τῆς</span> <span class=\"greek\">μερίδος</span>. A tradução “cidade principal do distrito da Macedônia” (por exemplo, Beyer, Steinmann, Bauernfeind, NRSV) é tolerável apenas na falta de alternativa melhor. Quanto à forma, falta o artigo com <span class=\"greek\">πρώτη</span> e, quanto ao assunto, Filipos não era a capital (sentido de <span class=\"greek\">πρώτη</span> num contexto assim: Ps.-Scylax, Peripl. 35 [BFabricius 1878]; escólio a Pind., O. 8, 1h; cf. 6, 144g; Eunap. 7; 96; Procop., Aedif. 5, 4, 18 <span class=\"greek\">μητρόπολις</span> … <span class=\"greek\">οὕτω</span> <span class=\"greek\">πόλιν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">πρώτην</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἔθνους</span> <span class=\"greek\">καλοῦσι</span> <span class=\"greek\">Ῥωμαῖοι</span>) nem da província da Macedônia nem de qualquer de seus distritos. O texto de Nestle segue Blass, que preferiu a conjectura de Johannes Clericus (LeClerc), e lê <span class=\"greek\">πρώτη</span>[<span class=\"greek\">ς</span>] <span class=\"greek\">μερίδος</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">Μακεδονίας</span>, “do primeiro distrito da Macedônia”, com referência ao fato de que os romanos (Livy 45, 29) dividiram a Macedônia em quatro <span class=\"greek\">μερίδες</span>=distritos em 167 a.C. (assim também Hoennicke, Preuschen, Wlh., Zahn; Field, Notes 124; EHaupt, Gefangenschaftsbriefe7 1902, 83s.; Belser; Zürcher Bibel ’31; Haenchen ad loc.; RBorger, TRu 52, ’87, 37s. Sobre as variantes textuais, ver Metzger, Textual Commentary ad loc. Ver também AClark e JLarsen s.v. <span class=\"greek\">κεφαλή</span> 2b, final.—Se a reconstituição do texto aparentemente danificado resultar numa redação que permita relacionar <span class=\"greek\">πρώτη</span> à progressão de uma viagem, poderíamos comparar Arrian, Anab. 4, 23, 3 <span class=\"greek\">ἡ</span> <span class=\"greek\">πρώτη</span> <span class=\"greek\">καθ</span>’ <span class=\"greek\">ὁδὸν</span> <span class=\"greek\">πόλις</span>; Appian, Bell. Civ. 2, 35 §137 Ariminum <span class=\"greek\">ἐστὶν</span> <span class=\"greek\">Ἰταλίας</span> <span class=\"greek\">πρώτη</span> [isto é, <span class=\"greek\">πόλις</span>] <span class=\"greek\">μετὰ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">Γαλατίαν</span> = a primeira cidade da Itália depois de [sair da] Gália; Ps.-Scylax §67: partindo da Tessália, a <span class=\"greek\">πρώτη</span> <span class=\"greek\">πόλις</span> <span class=\"greek\">Μακεδονίας</span> é <span class=\"greek\">Ἡράκλειον</span>.—Linguisticamente, <span class=\"greek\">πρ</span>. <span class=\"greek\">πόλ</span>. também pode, naturalmente, ter sentido temporal e significar a primeira cidade em que algo acontece [Diod S 12, 67, 2, Acanto foi a primeira cidade, <span class=\"greek\">πρ</span>. <span class=\"greek\">πόλ</span>., a rebelar-se contra Atenas]).</p><p class=\"entry-text\">② Parte, porção, quinhão (Demosth. 43, 82; Plut., Ages. 17, 5; Lucian, De Merc. Cond. 26; Vett. Val. 345, 16; SIG 1013, 4; BGU 996 III, 1; PLond III, 880, 18ss. p. 9 [113 a.C.]; POxy 1482, 21; LXX): <span class=\"greek\">τὴν</span> <span class=\"greek\">ἀγαθὴν</span> <span class=\"greek\">μ</span>. <span class=\"greek\">ἐκλέγεσθαι</span>, escolher a melhor parte <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.42\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:42</a> (figuradamente, de alimento? Cf. Mft., tradução, “Maria escolheu o melhor prato”, e ver Gen 43:34; 1 Km 9:23, mas contra essa posição TGillieson, ET 59, ’47/48, 111s. Para outras referências, Field, Notes 63s.; HAlmqvist, Plutarch u. d. NT ’46, 65). <span class=\"greek\">μ</span>. <span class=\"greek\">κυρίου</span>, parte do Senhor 1 Cl 29:2 (Dt 32:9); cf. 30:1. <span class=\"greek\">τίς</span> <span class=\"greek\">μερὶς</span> <span class=\"greek\">πιστῷ</span> <span class=\"greek\">μετὰ</span> <span class=\"greek\">ἀπίστου</span>;, que tem em comum o crente com o descrente? (isto é, com referência à mesma coisa; sobre <span class=\"greek\">μετά</span>, ver abaixo) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.6.15\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 6:15</a>. Semelhantemente, <span class=\"greek\">μετὰ</span> <span class=\"greek\">μοιχῶν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">μερίδα</span> <span class=\"greek\">σου</span> <span class=\"greek\">ἐτίθεις</span>, juntaste tua sorte à dos adúlteros 1 Cl 35:8 (Ps 49:18). <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔστιν</span> <span class=\"greek\">σοι</span> <span class=\"greek\">μ</span>. <span class=\"greek\">οὐδὲ</span> <span class=\"greek\">κλῆρος</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">λόγῳ</span> <span class=\"greek\">τούτῳ</span>, não tens parte nem sorte neste assunto <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:21</a> (cf. Dt 12:12 <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔστιν</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">οὐδὲ</span> <span class=\"greek\">κλῆρος</span> <span class=\"greek\">μεθ</span>’ <span class=\"greek\">ὑμῶν</span>.—<span class=\"greek\">μ</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">κλῆρος</span> também TestSol 14:5 e Philo, Plant. 60.—<span class=\"greek\">μ</span>. <span class=\"greek\">ἐν</span> como em 2 Km 20:1; TestJob 38:2 <span class=\"greek\">ἐν</span> <span class=\"greek\">γῇ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">σποδῷ</span>). <span class=\"greek\">ἡ</span> <span class=\"greek\">μερὶς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κλήρου</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἁγίων</span>, parte na herança dos santos (cf. 1QS 11:7s.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:12</a>.—DELG s.v. <span class=\"greek\">μείρομαι</span> II p. 679. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0231-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μερισμός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μερισμός</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">μερίζω</span>; Pla. e posteriores; inscrições, papiros, LXX, TestJob 46:1; Philo; Jos., C. Ap. 2, 203; Ar. 6, 1; Tat. 5, 1).</p><p class=\"entry-text\">① Divisão, separação.</p><p class=\"entry-text\">ⓐ <span class=\"greek\">ἄχρι</span> <span class=\"greek\">μερισμοῦ</span> <span class=\"greek\">ψυχῆς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πνεύματος</span>, até a separação de alma e espírito, isto é, a ponto de separar alma e espírito <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 4:12</a>.</p><p class=\"entry-text\">ⓑ Em Inácio, com referência aos dissidentes, que se separaram: (a) divisão, em parte como ação, em parte como resultado IPhld 2:1; 3:1; 8:1; plural ISm 7:2. <span class=\"greek\">ὥ</span> <span class=\"greek\">προειδότα</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">μ</span>. <span class=\"greek\">τινων</span>, como alguém que conhecia de antemão a divisão causada por certas pessoas IPhld 7:2.</p><p class=\"entry-text\">② Distribuição, repartição (Aeneas Tact. linha 27; Polyb. 31, 10, 1; SIG 1017, 16 [século III a.C.]; TestJob 46:1; Josh 11:23; Philo, Poster. Cai. 90): <span class=\"greek\">ἁγίου</span> <span class=\"greek\">πνεύματος</span> <span class=\"greek\">μερισμοί</span>, distribuições do Espírito Santo, isto é, dos diversos dons procedentes do Espírito Santo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:4</a>. AcPl Ha 8, 18 <span class=\"greek\">κατὰ</span> … <span class=\"greek\">μ</span>. <span class=\"greek\">λαμβάνοντες</span>//Ox 1602, 22 <span class=\"greek\">κατὰ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">λαβόντες</span>//BMM recto 22–24.—DELG s.v. <span class=\"greek\">μείρομαι</span> II. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0231-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεριστής, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μεριστής</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">μερίζω</span>; SEG VIII, 551, 25 [século I a.C.]; Pollux 4, 176; Vett. Val. 62, 4; PGM 13, 638, epíteto de Serápis), repartidor, árbitro <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.14\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:14</a> (omitido em variante textual).—DELG s.v. <span class=\"greek\">μείρομαι</span> II. M-M. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0231-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μέρος, ους, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μέρος</span>, <span class=\"greek\">ους</span>, <span class=\"greek\">τό</span> (Pind., Hdt. e posteriores).</p><p class=\"entry-text\">① Parte, em contraste com o todo.</p><p class=\"entry-text\">ⓐ Em geral (Ocellus Luc. c. 12 <span class=\"greek\">τὸ</span> <span class=\"greek\">πᾶν</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">μέρος</span> <span class=\"greek\">τι</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">παντός</span>; Alex. Aphr., An. II 1 p. 13, 16 <span class=\"greek\">μ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">ὅλῳ</span>; Gen 47:24; Philo, Spec. Leg. 3, 189 <span class=\"greek\">τ</span>. <span class=\"greek\">ὅλου</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">μερῶν</span> e outros; Ath. 12, 3 <span class=\"greek\">μικρῷ</span> <span class=\"greek\">μέρει</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">παντὸς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πᾶν</span> … <span class=\"greek\">δοκιμάζουσιν</span>), com genitivo do todo: <span class=\"greek\">τὸ</span> <span class=\"greek\">ἐπιβάλλον</span> <span class=\"greek\">μ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">οὐσίας</span>, a parte dos bens que me cabe <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 15:12</a> (SIG 346, 36 <span class=\"greek\">τὸ</span> <span class=\"greek\">μέρος</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἐπιβάλλον</span>; 1106, 80). <span class=\"greek\">μ</span>. <span class=\"greek\">τι</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἀγροῦ</span>, parte do campo Hs 5, 2, 2. <span class=\"greek\">δύο</span> <span class=\"greek\">μέρη</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ῥάβδου</span>, dois terços da vara (Thu. 1, 104, 2 <span class=\"greek\">τῆς</span> <span class=\"greek\">Μέμφιδος</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">δύο</span> <span class=\"greek\">μερῶν</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">τρίτον</span> <span class=\"greek\">μέρος</span>; SIG 975, 24s.) Hs 8, 1, 12s.; cf. 8, 5, 3ss.; 8, 8, 4; 8, 9, 1. <span class=\"greek\">τὸ</span> <span class=\"greek\">πλεῖστον</span> <span class=\"greek\">μ</span>. <span class=\"greek\">αὐτῶν</span> 8, 2, 9; cf. 9, 7, 4 e 8, 1, 16. <span class=\"greek\">τὰ</span> <span class=\"greek\">λοιπὰ</span> <span class=\"greek\">μ</span>. 8, 1, 15. Também sem genitivo, quando o contexto deixa claro o contraste entre parte e todo: <span class=\"greek\">μὴ</span> <span class=\"greek\">ἔχον</span> <span class=\"greek\">μέρος</span> <span class=\"greek\">τι</span> <span class=\"greek\">σκοτεινόν</span>, sem possuir parte alguma escura <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.36\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:36</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.23\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:23</a> (Jos., Ant. 1, 172 <span class=\"greek\">μέρη</span> <span class=\"greek\">τέσσαρα</span> <span class=\"greek\">ποιήσαντες</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.16.19\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 16:19</a>; Hv 4, 3, 4s. Dos cristãos: <span class=\"greek\">ἐκλογῆς</span> <span class=\"greek\">μ</span>., porção escolhida dentre toda a humanidade 1 Cl 29:1.</p><p class=\"entry-text\">ⓑ Empregos especializados:</p><p class=\"entry-text\"><span class=\"greek\">α</span>. Componente, elemento: <span class=\"greek\">τινὰ</span> <span class=\"greek\">μέρη</span> <span class=\"greek\">ἔχουσιν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἀνομίας</span>, eles ainda têm certos elementos de iniquidade Hv 3, 6, 4b.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Partes do corpo (Diod S 32, 12, 1 <span class=\"greek\">τὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">σώματος</span> <span class=\"greek\">μέρη</span>; Dio Chrys. 16 [33], 62; Plut., Mor. 38a <span class=\"greek\">μ</span>. <span class=\"greek\">τ</span>. <span class=\"greek\">σώματος</span>; Artem. 3, 51 e outros; Herodian 8, 4, 10; PRyl 145, 14 [38 d.C.]; PGM 4, 2390; 2392; Tat. 16, 1); figuradamente, do corpo cuja cabeça é Cristo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:16</a> (sobre o texto, ver <span class=\"greek\">μέλος</span> 2; quanto à ideia, <span class=\"greek\">σῶμα</span>, final).</p><p class=\"entry-text\"><span class=\"greek\">γ</span>. <span class=\"greek\">τὰ</span> <span class=\"greek\">μέρη</span>, as partes (de uma área geográfica), região, distrito (Herodian 6, 5, 7; Jos., Ant. 12, 234; B-D-F §141, 2; ver Rob. 408): <span class=\"greek\">τῆς</span> <span class=\"greek\">Γαλιλαίας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:22</a>. <span class=\"greek\">τὰ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">Λιβύης</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">Κυρήνην</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:10</a>; cf. 20:2. Também de um distrito numa cidade ou nas proximidades (cf. UPZ 180b, 8 [113 a.C.] <span class=\"greek\">οἰκίας</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">οὔσης</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">νότου</span> <span class=\"greek\">μέρει</span> <span class=\"greek\">Διὸς</span> <span class=\"greek\">πόλεως</span>): <span class=\"greek\">τὰ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">Τύρου</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">Σιδῶνος</span>, a região de Tiro e Sidom <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:21</a>; cf. 16:13; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 8:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.1\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:1</a> D; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.43\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:43</a> D. <span class=\"greek\">τὰ</span> <span class=\"greek\">ἀνωτερικὰ</span> <span class=\"greek\">μέρη</span>, as regiões superiores (=do interior), o interior (cf. PHamb 54 I, 14 <span class=\"greek\">τὰ</span> <span class=\"greek\">ἄνω</span> <span class=\"greek\">μέρη</span>, sobre o alto vale do Nilo) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:1</a>.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.9\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:9</a> (ver <span class=\"greek\">κατώτερος</span>).</p><p class=\"entry-text\"><span class=\"greek\">δ</span>. Lado (Diod S 2, 9, 3 <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">ἑκάτερον</span> <span class=\"greek\">μέρος</span>=dos dois lados; Ex 32:15; 1 Macc 9:12; TestJud 5:4; Ath. 1, 4 <span class=\"greek\">τὸ</span> <span class=\"greek\">ἕτερον</span> … <span class=\"greek\">τῆς</span> <span class=\"greek\">κεφαλῆς</span> <span class=\"greek\">μέρος</span>) Hs 9, 2, 3. <span class=\"greek\">τὰ</span> <span class=\"greek\">δεξιὰ</span> <span class=\"greek\">μ</span>., do lado direito; <span class=\"greek\">τὰ</span> <span class=\"greek\">ἀριστερὰ</span> <span class=\"greek\">μ</span>., do lado esquerdo v 3, 1, 9; 3, 2, 1. De uma embarcação: <span class=\"greek\">τὰ</span> <span class=\"greek\">δεξιὰ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">πλοίου</span>, o lado direito do barco (como lado auspicioso? cf. Il. 12, 239; 13, 821, sobre uma ave agourenta) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.21.6\" target=\"_blank\" rel=\"noopener noreferrer\">J 21:6</a> (de uma parte do corpo POxy 3195, II 40, 43 [331 d.C.]). <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐξώτερα</span> <span class=\"greek\">μ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">οἰκοδομῆς</span>, a parte exterior do edifício Hs 9, 9, 3.—New Docs 3, 75.</p><p class=\"entry-text\"><span class=\"greek\">ε</span>. Pedaço: <span class=\"greek\">ἰχθύος</span> <span class=\"greek\">ὀπτοῦ</span> <span class=\"greek\">μέρος</span>, pedaço de peixe assado <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.42\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:42</a>.—<span class=\"greek\">μ</span>. <span class=\"greek\">τι</span> <span class=\"greek\">λαμβάνειν</span>, receber uma porção Hv 3, 1, 6.</p><p class=\"entry-text\"><span class=\"greek\">ζ</span>. Partido (Jos., Bell. 1, 143; POxy 1278, 24; PFlor 47, 17; PLond III, 1028, 18 p. 277 [século VII d.C.] <span class=\"greek\">τοῦ</span> <span class=\"greek\">πρασίνου</span> <span class=\"greek\">μέρους</span>=“do partido verde”) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 23:6</a>. <span class=\"greek\">τινὲς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">γραμματέων</span> <span class=\"greek\">τ</span>. <span class=\"greek\">μέρους</span> <span class=\"greek\">τ</span>. <span class=\"greek\">Φαρισαίων</span> v. 9.</p><p class=\"entry-text\"><span class=\"greek\">η</span>. Ramo ou setor de atividade (cf. PFlor 89, 2, segundo Preisigke, Berichtigungsliste 1922, 147 <span class=\"greek\">τὰ</span> <span class=\"greek\">μέρη</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">διοικήσεως</span>=“os ramos da administração”) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:27</a>.</p><p class=\"entry-text\"><span class=\"greek\">θ</span>. Assunto, questão, matéria (Menand., Epitr. 234 S. [58 Kö.], Per. 297 S. [107 Kö.]; Diod S 2, 27, 1; <span class=\"greek\">Περὶ</span> <span class=\"greek\">ὕψους</span> 12, 5 [<span class=\"greek\">μέρη</span>=objetos]; Jos., Ant. 15, 61 <span class=\"greek\">τούτῳ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">μέρει</span>; PRyl 127, 12 [29 d.C.] <span class=\"greek\">ἀναζητῆσαι</span> <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">μέρους</span>=“iniciar uma investigação acerca do assunto”): <span class=\"greek\">ἐν</span> <span class=\"greek\">τούτῳ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">μέρει</span>, neste caso, nesta questão (cf. Polyb. 18, 18, 2 <span class=\"greek\">τ</span>. <span class=\"greek\">πίστιν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τούτῳ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">μέρει</span> <span class=\"greek\">διαφυλάττειν</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 3:10</a>; 9:3 (ver também <span class=\"greek\">ἐν</span> <span class=\"greek\">μέρει</span> em c abaixo). Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 4:16</a>, variante textual.</p><p class=\"entry-text\">ⓒ Empregado com preposições: <span class=\"greek\">ἀνὰ</span> <span class=\"greek\">μέρος</span>, um após o outro, sucessivamente (ver <span class=\"greek\">ἀνά</span> 2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.27\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:27</a>.—<span class=\"greek\">ἀπὸ</span> <span class=\"greek\">μέρους</span>, em parte (Dio Chrys. 28 [45], 3; Ael. Aristid. 32, 4 K.=12 p. 135 D.; Ptolem., Apotel. 2, 10, 2; Epict. 1, 27, 17 <span class=\"greek\">δι</span>’ <span class=\"greek\">ὅλων</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">ἀ</span>. <span class=\"greek\">μ</span>.; PRyl 133, 17; BGU 1201, 15 [2 d.C.]; PTebt 402, 2; POxy 1681, 9; Just., A II, 10, 8 <span class=\"greek\">Χριστῷ</span> … <span class=\"greek\">τῷ</span> … <span class=\"greek\">ἄ</span>. <span class=\"greek\">μ</span>. <span class=\"greek\">γνωσθέντι</span>): <span class=\"greek\">πώρωσις</span> <span class=\"greek\">ἀ</span>. <span class=\"greek\">μ</span>., endurecimento parcial <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 11:25</a>. <span class=\"greek\">τολμηρότερον</span> … <span class=\"greek\">ἀ</span>. <span class=\"greek\">μ</span>., muito ousadamente em alguns pontos 15:15. <span class=\"greek\">καθὼς</span> <span class=\"greek\">ἐπέγνωτε</span> <span class=\"greek\">ἡμᾶς</span> <span class=\"greek\">ἀ</span>. <span class=\"greek\">μ</span>., assim como nos conhecestes em parte <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:14</a>. Também por algum tempo: <span class=\"greek\">ἀ</span>. <span class=\"greek\">μ</span>. <span class=\"greek\">ἐμπλησθῆναί</span> <span class=\"greek\">τινος</span>, desfrutar por algum tempo da companhia de alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 15:24</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 2:5</a>, em alguma medida.—<span class=\"greek\">ἐκ</span> <span class=\"greek\">μέρους</span>, em parte, individualmente (Ael. Aristid. 54 p. 695 D.; 698; SIG 852, 30 … <span class=\"greek\">ὅλη</span>, <span class=\"greek\">ἐκ</span> <span class=\"greek\">μέρους</span> <span class=\"greek\">δέ</span> … ; PLond III, 1166, 14 p. 105 [42 d.C.]; BGU 538, 33; PRyl 233, 6; Philo, Mos. 2, 1 e outros): individualmente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.27\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 12:27</a>. <span class=\"greek\">ἐκ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">γινώσκειν</span>, conhecer em parte 13:9a, 12; cf. v. 9b. <span class=\"greek\">τὸ</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">μ</span>., o que é “em parte” = imperfeito v. 10.—<span class=\"greek\">ἐν</span> <span class=\"greek\">μέρει</span>, no tocante a, quanto a (Antig. Car. 24; Diod S 20, 58, 5; Plut., Mor. 102e; Horapollo 1, 57 <span class=\"greek\">ἐν</span> <span class=\"greek\">τροφῆς</span> <span class=\"greek\">μέρει</span>=“como alimento”; GDI 5185, 30 [Creta] <span class=\"greek\">ἐν</span> <span class=\"greek\">χάριτος</span> <span class=\"greek\">μέρει</span>; Philo, Det. Pot. Ins. 5 <span class=\"greek\">ἐν</span> <span class=\"greek\">μέρει</span> <span class=\"greek\">λόγου</span> e outros): <span class=\"greek\">ἐν</span> <span class=\"greek\">μέρει</span> <span class=\"greek\">ἑορτῆς</span>, quanto a uma festa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:16</a> (cf. ApcrEzk [Epiph. 70, 14] <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">μέρει</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀδυναμίας</span>, “em relação à minha incapacidade”. Ver b<span class=\"greek\">θ</span> acima).—<span class=\"greek\">κατὰ</span> <span class=\"greek\">μέρος</span>, parte por parte, detalhadamente (inscrições [ver SIG índice IV p. 444a]; PTebt 6, 24): <span class=\"greek\">περὶ</span> <span class=\"greek\">ὧν</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔστιν</span> <span class=\"greek\">νῦν</span> <span class=\"greek\">λέγειν</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">μέρος</span> (<span class=\"greek\">κ</span>. <span class=\"greek\">μ</span>., sobre o tratamento detalhado de um assunto, como em Pla., Theaet. 157b, Soph. 246c; Polyb. 1, 4, 6; 3, 19, 11; 3, 28, 4; 10, 27, 7 <span class=\"greek\">λέγειν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">μ</span>.; Ptolem., Apotel. 2, 11, 7; 2 Macc 2:30; Jos., Ant. 12, 245), ponto por ponto <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.5\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:5</a>.—<span class=\"greek\">παρὰ</span> <span class=\"greek\">μέρος</span>, para um lado (Appian, Liby. 14 §55 <span class=\"greek\">γιγνόμενος</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">μ</span>.=afastar-se para um lado, Bell. Civ. 5, 81 §345; PGM 13, 438 <span class=\"greek\">βάλε</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">μέρος</span>=“põe de lado”): <span class=\"greek\">ὁ</span> <span class=\"greek\">λίθος</span> <span class=\"greek\">ὑπεχώρησε</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">μ</span>., a pedra recuou para um lado GPt 9:37.</p><p class=\"entry-text\">ⓓ Acusativo adverbial <span class=\"greek\">μέρος</span> <span class=\"greek\">τι</span>, em parte, parcialmente (Thu. 2, 64; 4, 30, 1; X., Eq. 1, 12; SIG 976, 65; 1240, 8 <span class=\"greek\">ἤτι</span> <span class=\"greek\">μέρος</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">σύμπαν</span>; 3 Km 12:31) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:18</a>; <span class=\"greek\">τὸ</span> <span class=\"greek\">πλεῖστον</span> <span class=\"greek\">μ</span>., na maior parte (Menand., Fgm. 789 Kö.; Diod S 22, 10, 5) Hs 8, 5, 6; 8, 10, 1. <span class=\"greek\">τὸ</span> <span class=\"greek\">πλεῖον</span> <span class=\"greek\">μ</span>., em sua maior parte v 3, 6, 4a.</p><p class=\"entry-text\">② Quinhão, participação (Trag. e outros): <span class=\"greek\">μ</span>. <span class=\"greek\">τι</span> <span class=\"greek\">μεταδοῦναι</span> <span class=\"greek\">ἀπό</span> <span class=\"greek\">τινος</span>, dar uma parte de alguma coisa 1:5 (sobre <span class=\"greek\">μέρος</span> <span class=\"greek\">ἀπό</span> <span class=\"greek\">τινος</span>, cf. PStras 19, 5 [105 d.C.] <span class=\"greek\">τοῦ</span> <span class=\"greek\">ὑπάρχοντος</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">μέρους</span> <span class=\"greek\">ἑνὸς</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">μερῶν</span> <span class=\"greek\">ἐννέα</span>); <span class=\"greek\">δώσω</span> <span class=\"greek\">αὐτοῖς</span> … <span class=\"greek\">μέρος</span> <span class=\"greek\">δικαιοσύνης</span> <span class=\"greek\">μετὰ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἁγίων</span> <span class=\"greek\">μου</span>, darei a eles … uma parte de justiça junto com meus santos, isto é, aqueles que foram salvos da perdição desfrutarão da mesma condição redimida dos que já se encontram na presença divina ApcPt Rainer 6. <span class=\"greek\">ἔχειν</span> <span class=\"greek\">μ</span>. <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span>, ter participação em alguma coisa (cf. Synes., Ep. 58 p. 203a <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔστι</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">διαβόλῳ</span> <span class=\"greek\">μέρος</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">παραδείσῳ</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.20.6\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 20:6</a> (Dalman, Worte 103s.). <span class=\"greek\">ἀφελεῖ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">μέρος</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ξύλου</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ζωῆς</span> 22:19.—Lugar (Appian, Bell. Civ. 1, 34 §154 <span class=\"greek\">ἐν</span> <span class=\"greek\">ὑπηκόων</span> <span class=\"greek\">ἀντὶ</span> <span class=\"greek\">κοινωνῶν</span> <span class=\"greek\">εἶναι</span> <span class=\"greek\">μέρει</span>=ocupar o lugar de súditos em vez de parceiros): <span class=\"greek\">τὸ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">αὐτῶν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">λίμνῃ</span>, o lugar deles é no lago <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.8\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 21:8</a>. <span class=\"greek\">ἔχειν</span> <span class=\"greek\">μ</span>. <span class=\"greek\">μετά</span> <span class=\"greek\">τινος</span>, ter lugar com alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.8\" target=\"_blank\" rel=\"noopener noreferrer\">J 13:8</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">τινὸς</span> <span class=\"greek\">μετὰ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ὑποκριτῶν</span> <span class=\"greek\">τιθέναι</span>, designar a alguém um lugar entre os fingidos (hipócritas) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.51\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:51</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.46\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:46</a>. <span class=\"greek\">μετ</span>’ <span class=\"greek\">αὐτῶν</span> <span class=\"greek\">μοι</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">γένοιτο</span> <span class=\"greek\">σχεῖν</span> <span class=\"greek\">ἐν</span> (variante textual <span class=\"greek\">παρὰ</span>) <span class=\"greek\">θεῷ</span>, que eu tenha meu lugar com eles em Deus (ou junto de Deus) IPol 6:1. <span class=\"greek\">τοῦ</span> <span class=\"greek\">λαβεῖν</span> <span class=\"greek\">μ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">ἀριθμῷ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">μαρτύρων</span> MPol 14:2.—B. 934. DELG s.v. <span class=\"greek\">μείρομαι</span> II. M-M. EDNT. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0231-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεσάζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μεσάζω</span> (ver <span class=\"greek\">μεσόω</span>; Hippocr. e outros; Diod S 1, 32, 9; PSI 151, 6; Wsd 18:14), estar no meio ou na metade <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.14\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:14</a>, variante textual (Ps.-Callisth. 3, 26, 7 p. 127, 2 <span class=\"greek\">θέρους</span> <span class=\"greek\">μεσάζοντος</span>); ver <span class=\"greek\">μεσόω</span>.—DELG s.v. <span class=\"greek\">μέσος</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0231-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεσημβρία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μεσημβρία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">μέσος</span>, <span class=\"greek\">ἡμέρα</span>; ver Schwyzer I 277 sobre a mudança <span class=\"greek\">μβρ</span>; “meio-dia”, Aeschyl., Hdt. e posteriores; inscrições, papiros, LXX, JosAs; SyBar 12:2; ApcEsdr 4:22 p. 28, 25 Tdf.; Philo, Joseph.).</p><p class=\"entry-text\">① De tempo: meio-dia (Aeschyl., Hdt. e outros; PRyl 27, 66; PGM 7, 157. Assim, em regra, na LXX; Jos., Ant. 11, 155) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.22.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 22:6</a>; GPt 5:15. <span class=\"greek\">κατὰ</span> <span class=\"greek\">μεσημβρίαν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:26</a>, por volta do meio-dia (Philo, Somn. 1, 202; assim EbNestle, StKr 65, 1892, 335–37; Wendt e outros).</p><p class=\"entry-text\">② De lugar: sul (Hdt. 1, 6; 142; 2, 8 e outros; SIG 972, 96; 1112, 26; Da 8:4, 9; Philo; JosAs 2:13; ApcEsdr 4:22 p. 28, 25 Tdf.; Jos., Bell. 5, 505; SibOr 3, 26), por ser a posição do sol ao meio-dia: <span class=\"greek\">κατὰ</span> <span class=\"greek\">μεσημβρίαν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:26</a>, para o sul (ver B-D-F §253, 5; Preuschen, Zahn, Bauernfeind, Haenchen ad loc.—Conzelmann [Hermeneia] não se decide entre 1 e 2).—B. 873; 996. DELG s.v. <span class=\"greek\">μέσος</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0231-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεσιτεύω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μεσιτεύω</span> (de <span class=\"greek\">μεσίτης</span>), 1º aoristo <span class=\"greek\">ἐμεσίτευσα</span>. Do sentido “mediar, atuar como fiador” (Aristot. e outros; OGI 437, 76 [século I a.C.]; 79; BGU 906, 7; CPR I, 1, 19; 206, 13; Philo), intransitivo (Jos., Ant. 7, 193; 16, 118 “atuar como mediador, pacificador”), deriva facilmente o sentido garantir, no sentido de resolver uma questão, <span class=\"greek\">ὅρκῳ</span>, mediante juramento <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.17\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6:17</a>.—DELG s.v. <span class=\"greek\">μέσος</span> B. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0231-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεσίτης, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μεσίτης</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (ver <span class=\"greek\">μεσιτεύω</span>; desde Polyb. 28, 17, 8; Ps.-Lucian, Amor. 47 <span class=\"greek\">θεὸν</span> <span class=\"greek\">μεσίτην</span> <span class=\"greek\">λαβόντες</span>; papiros; Job 9:33; TestDan 6:2; AssMos Fgm. a; Philo; Jos., Ant. 4, 133; 16, 24. Sobre este diversificado termo técnico do direito helenístico, ver LMitteis, Her 30, 1895, 616ss.; JBehm, D. Begriff <span class=\"greek\">Διαθήκη</span> im NT 1912, 77ss., com numerosos exemplos; ver bibliografia em JModrzejewski, Private Arbitration in Greco-Roman Egypt, JJP 6, ’52, 247 n. 79), alguém que medeia entre duas partes para remover uma divergência ou alcançar um objetivo comum: mediador, árbitro. De Cristo (Mitra como <span class=\"greek\">μεσίτης</span>: Plut., Mor. 369e), com genitivo das pessoas entre as quais atua como mediador: <span class=\"greek\">μ</span>. <span class=\"greek\">θεοῦ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀνθρώπων</span>, mediador entre Deus e os seres humanos (Iren. 3, 18, 7 [Harv. II 100, 7]; cf. TestDan 6:2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 2:5</a>; com genitivo daquilo de que Jesus é mediador: <span class=\"greek\">κρείττονος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.8.6\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 8:6</a>, <span class=\"greek\">καινῆς</span> 9:15, <span class=\"greek\">νέας</span> <span class=\"greek\">διαθήκης</span> 12:24 (ver <span class=\"greek\">διαθήκη</span> 2. AssMos. Fgm. a, Denis 63, 10=Tromp p. 272], Moisés se denomina <span class=\"greek\">τῆς</span> <span class=\"greek\">διαθήκης</span> <span class=\"greek\">μεσίτης</span>). Da lei: <span class=\"greek\">διαταγεὶς</span> <span class=\"greek\">δι</span>’ <span class=\"greek\">ἀγγέλων</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">χειρὶ</span> <span class=\"greek\">μεσίτου</span>, ordenada por meio de anjos, pela mão de um mediador <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.19\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 3:19</a> (Moisés, como mediador entre Deus e o povo, denominado <span class=\"greek\">μεσίτης</span>, por exemplo, Philo, Mos. 2, 166, Somn. 1, 143; Betz, Gal [Hermeneia] ad loc.). O sentido do v. 20, <span class=\"greek\">ὁ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">ἑνὸς</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔστιν</span>, um intermediário não existe para uma única parte, é debatido. Provavelmente significa que a atividade do intermediário pressupõe mais de uma parte e, por isso, pode ser insatisfatória, visto que precisa resultar num compromisso. A presença de um intermediário impediria que se alcançasse, sem qualquer obstáculo, o propósito do <span class=\"greek\">εἷς</span> <span class=\"greek\">θεός</span> ao dar a lei.—NKZ 39, 1928, 21–24; 549–52; 552s.; HStegmann, BZ 22, ’34, 30–42; Straub 67.—DELG s.v. <span class=\"greek\">μέσος</span> B. M-M. EDNT. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0231-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεσονύκτιον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μεσονύκτιον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (<span class=\"greek\">μέσος</span>, <span class=\"greek\">νύξ</span>; substantivo neutro de <span class=\"greek\">μεσονύκτιος</span> [Pind. e outros]; como substantivo, Hippocr. e outros; Diod S 20, 48, 6; Chariton 1, 9, 1; POxy 1768, 6; LXX; TestJob 31:5 <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">μ</span>. A grafia <span class=\"greek\">μεσανύκτιον</span> é pouco atestada [POxy 1768, 6 do século III d.C.. Cf. B-D-F §35, 2; W-S. §5, 20b; Mlt-H. 73]. Sobre a formação, ver B-D-F §123, 1; W-S. §16, 5; Mlt-H. 341; Phryn. p. 53 Lob.), meia-noite; <span class=\"greek\">μεσονύκτιον</span>, acusativo de tempo, à meia-noite <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:35</a> (Hippocr. VII p. 72 Littré; Ps 118:62.—PGM 13, 680 <span class=\"greek\">τὸ</span> <span class=\"greek\">μεσονύκτιον</span>). Também o genitivo (assim lido na passagem de Hippocr. citada, pela edição de Kühn II p. 260; ver B-D-F §186, 2), <span class=\"greek\">μεσονυκτίου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:5</a>. <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">μ</span>., por volta da meia-noite (Strabo 2, 5, 42) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:25</a>. <span class=\"greek\">μέχρι</span> <span class=\"greek\">μεσονυκτίου</span>, até a meia-noite 20:7 (sobre a omissão do artigo, ver B-D-F §255, 3; Rob. 792).—DELG s.v. <span class=\"greek\">μέσος</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0231-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μεσοποταμία, ας, ἡ</h1><div class=\"entry-meta\"><span>nome geográfico feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Μεσοποταμία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (substantivo feminino de <span class=\"greek\">μεσοποτάμιος</span>, <span class=\"greek\">α</span>, <span class=\"greek\">ον</span> = “situado entre rios”. <span class=\"greek\">ἡ</span> <span class=\"greek\">μεσοποταμία</span>, subentende-se <span class=\"greek\">χώρα</span> = “a terra entre rios” [Polyb. 5, 44, 6; Strabo 11, 12, 2], especialmente entre o Eufrates e o Tigre), Mesopotâmia (Diod S 2, 11, 2; 18, 6, 3; Appian, Syr. 48 §246; 53 §269; Arrian, Anab. 3, 7, 3; 7, 7, 3; Polyaenus, Exc. 9, 2; Ptolem., Apotel. 2, 3, 22; 28; OGI 54, 18; LXX; Demetr.: 722 Fgm. 1, 1s. Jac.; Philo, Joseph.; TestJud 9:1; 10:1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:9</a>. Na narrativa acerca de Abraão (cf. Gen 24:10) 7:2.—LDillemann, Haute Mésopotamie orient. et pays adjacents, ’62; Pauly-W. XV 1105–63; Kl. Pauly III 1237–41.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0231-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μέσος, η, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μέσος</span>, <span class=\"greek\">η</span>, <span class=\"greek\">ον</span> (Hom. e posteriores). A distinção entre “no meio” e “entre, no meio de” para <span class=\"greek\">μ</span>. é por vezes bastante fluida, e algumas das passagens citadas aqui podem ajustar-se igualmente às acepções 1 ou 2.</p><p class=\"entry-text\">① Relativo a uma posição central espacial ou temporal: médio, central, no meio.</p><p class=\"entry-text\">ⓐ Como adjetivo (de termos intermediários: Pla., Rep. 330b, Pol. 303a): <span class=\"greek\">ὁ</span> <span class=\"greek\">μέσος</span> <span class=\"greek\">αὐτῶν</span> <span class=\"greek\">ἀνήρ</span>, o homem no meio deles, aparentemente rodeado por eles Hs 9, 12, 7. <span class=\"greek\">μέσης</span> <span class=\"greek\">νυκτός</span>, à meia-noite (3 Km 3:20.—B-D-F §270, 2; Rob. 495; Lobeck, Phryn. p. 53; 54; 465) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:6</a>. <span class=\"greek\">ἡμέρας</span> <span class=\"greek\">μέσης</span>, ao meio-dia (Jos., Bell. 1, 651, Ant. 17, 155) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 26:13</a>. <span class=\"greek\">εἰς</span> <span class=\"greek\">μέσην</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">οἰκοδομήν</span>, para o meio da construção Hs 9, 7, 5; cf. 9, 8, 2; 4; 6 (cf. Philo, Fuga 49 <span class=\"greek\">εἰς</span> <span class=\"greek\">μέσον</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ποταμόν</span>; Jos., Ant. 4, 80 <span class=\"greek\">εἰς</span> <span class=\"greek\">μέσον</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πῦρ</span>). <span class=\"greek\">ἐσταύρωσαν</span> … <span class=\"greek\">μέσον</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">Ἰησοῦν</span>, crucificaram Jesus entre (eles) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.18\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:18</a>. <span class=\"greek\">ἐσχίσθη</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">καταπέτασμα</span> <span class=\"greek\">μέσον</span>, a cortina rasgou-se em duas partes <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.45\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:45</a> (cf. Artem. 4, 30 <span class=\"greek\">τὸ</span> <span class=\"greek\">ἱμάτιον</span> <span class=\"greek\">μέσον</span> <span class=\"greek\">ἐρρωγέναι</span>). <span class=\"greek\">ἐλάκησεν</span> <span class=\"greek\">μέσος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:18</a> (cf. Aristoph., Ran. 955). <span class=\"greek\">ἐν</span> <span class=\"greek\">μέσοις</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ὀργάνοις</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">διαβόλου</span>, no meio dos instrumentos do diabo 2 Cl 18:2 (sobre a sintaxe, cf. Gen 2:9 <span class=\"greek\">ἐν</span> <span class=\"greek\">μέσῳ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">παραδείσῳ</span>).</p><p class=\"entry-text\">ⓑ Como substantivo neutro, <span class=\"greek\">τὸ</span> <span class=\"greek\">μ</span>., o meio (quanto à ausência do artigo, ver B-D-F §264, 4; cf. Rob. 792). <span class=\"greek\">ἀνὰ</span> <span class=\"greek\">μέσον</span> <span class=\"greek\">τινός</span> (ver <span class=\"greek\">ἀνά</span> 1): <span class=\"greek\">ἀνὰ</span> <span class=\"greek\">μέσον</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ὁρίων</span>, dentro da região ou através dela <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:31</a>. <span class=\"greek\">ἀνὰ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">αὐτῶν</span>, entre eles GPt 4:10; Hs 9, 2, 3; 9, 15, 2. <span class=\"greek\">ἀνὰ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">ἐκκλησίας</span> <span class=\"greek\">ἁγίων</span> B 6:16; 4:10; <span class=\"greek\">διακρῖναι</span> <span class=\"greek\">ἀνὰ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἀδελφοῦ</span>, distinguir entre um membro (da congregação) e outro <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 6:5</a> (ver <span class=\"greek\">ἀνά</span> 1b. Talvez <span class=\"greek\">μέσος</span> tenha provocado o encurtamento da frase, tornando-a obscura; cf. a expressão estoica <span class=\"greek\">μέσα</span> <span class=\"greek\">καθήκοντα</span> = <span class=\"greek\">καθήκοντα</span> <span class=\"greek\">ἃ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">μέσῳ</span> <span class=\"greek\">ἐστὶ</span> <span class=\"greek\">κατορθωμάτων</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἁμαρτημάτων</span>: MPohlenz, D. Stoa II ’49, 73s.). <span class=\"greek\">τὸ</span> <span class=\"greek\">ἀρνίον</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἀ</span>. <span class=\"greek\">μ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θρόνου</span>, o Cordeiro que está (assentado) no centro do trono <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.7.17\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 7:17</a>. <span class=\"greek\">ἀνὰ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">ὁδοῦ</span>, (percorreram) metade do caminho GJs 17:3.—<span class=\"greek\">διὰ</span> <span class=\"greek\">μέσου</span> <span class=\"greek\">αὐτῶν</span>, pelo meio deles (X., An. 1, 4, 4; Aesop. Fab. 147 P.=247 H.//201a Ch.//152 [I, II] H-H.; Am 5:17; Jer 44:4; Jdth 11:19; 1 Macc 5:46; Ath. 18, 3, “entre”) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.30\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:30</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.59\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:59</a>, variante textual. <span class=\"greek\">διὰ</span> <span class=\"greek\">μέσον</span> <span class=\"greek\">Σαμαρείας</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">Γαλιλαίας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 17:11</a> provavelmente só pode significar “através de Samaria e Galileia”; mas isso suscita dificuldade prática, pois seria de esperar a menção das províncias na ordem inversa. Talvez o texto esteja danificado (cf. as variantes textuais <span class=\"greek\">διὰ</span> <span class=\"greek\">μέσου</span> e <span class=\"greek\">μέσον</span>; ver B-D-F §222; Rob. 648; JBlinzler, AWikenhauser Festschr. ’54, 46ss. Se a variante <span class=\"greek\">διὰ</span> <span class=\"greek\">μέσου</span> <span class=\"greek\">Σ</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">Γ</span>. estiver correta, poder-se-ia comparar Maximus Tyr. 28, 4a <span class=\"greek\">διὰ</span> <span class=\"greek\">μέσου</span> <span class=\"greek\">πίστεως</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἀπιστίας</span>=através do espaço intermediário). Para a opinião segundo a qual <span class=\"greek\">μέσον</span> indica a área entre S. e G., ver os comentários. Cf. <span class=\"greek\">δια</span> B1.—<span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">μέσον</span>, para o meio ou centro (X., Cyr. 3, 1, 6; Dio Chrys. 19 [36], 24; 3 Km 6:8; Jos., Ant. 9, 149) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.35\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:35</a>; 5:19; 6:8; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.20.19\" target=\"_blank\" rel=\"noopener noreferrer\">J 20:19</a>, 26 (<span class=\"greek\">ἔστη</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">μέσον</span>, como em Vi. Aesopi G 82 P.); Hs 9, 8, 5; também no meio 9, 6, 1. Com genitivo (X., An. 1, 5; 14a; Jer 21:4; 48:7; Sb 6270, 13): <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">αὐτῶν</span>, no meio deles 9, 11, 7. Sem artigo (LXX; Jos., Vi. 334; SibOr 3, 674): <span class=\"greek\">εἰς</span> <span class=\"greek\">μ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">πεδίου</span>, no meio da planície Hs 9, 2, 1 (<span class=\"greek\">εἰς</span> <span class=\"greek\">μ</span>.=“no meio”, como em Ps.-Clem., Hom. 3, 30 p. 44, 21 Lag.). <span class=\"greek\">τί</span> … <span class=\"greek\">τὸ</span> <span class=\"greek\">ἔριον</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">μ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀκανθῶν</span> <span class=\"greek\">τιθέασιν</span>;, por que colocam a lã no meio dos espinhos? 7:11. <span class=\"greek\">ἀναστὰς</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">μ</span>., levantando-se (e apresentando-se) à frente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.60\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:60</a> (cf. Theocr. 22, 82 <span class=\"greek\">ἐς</span> <span class=\"greek\">μέσον</span>=no meio; Himerius, Or. 63 [=Or. 17], 2 <span class=\"greek\">εἰς</span> <span class=\"greek\">μέσον</span> <span class=\"greek\">ἔρχεσθαι</span>=vir a público; X., Cyr. 4, 1, 1 <span class=\"greek\">στὰς</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">μ</span>.).—<span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">μ</span>., entre, diante de (precisado pelo contexto, ou = em público [assim Clearch., Fgm. 45 <span class=\"greek\">οἴκοι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">μέσῳ</span>; Appian, Liby. 15 §63]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:6</a> (Dio Chrys. 30 [79], 39 <span class=\"greek\">ὀρχεῖσθαι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">μέσω</span>; Lucian, Pereg. 8) e para o meio, diante (deles) (Vi. Aesopi W c. 86 <span class=\"greek\">στὰς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">μέσῳ</span> <span class=\"greek\">ἔφη</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:7</a>. Sem artigo (LXX), <span class=\"greek\">ἐν</span> <span class=\"greek\">μέσῳ</span> (sobre a grafia <span class=\"greek\">ἐμ</span> <span class=\"greek\">μέσῳ</span>, encontrada várias vezes como variante textual, ver B-D-F §19, 1; Mlt-H. 105), em emprego absoluto, para o meio, diante (de alguém) (Appian, Hann. 16 §67, Liby. 14 §59; Jos., Ant. 7, 278) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.3\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:3</a>; MPol 18:1 e no meio (Pla., Rep. 558a; Herm. Wr. 4, 3; PLille 1 recto, 5 [259 a.C.]; GrBar 13:4) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.9\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:9</a>. Com genitivo de lugar (Aeneas Tact. 1529; 1532; TestAbr A 12 p. 90, 21 [Stone p. 28], B 8 p. 113, 3 [St. p. 74]; ParJer 1:2; GrBar 10:2): <span class=\"greek\">τῆς</span> <span class=\"greek\">θαλάσσης</span> (En 97:7), no meio do lago <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.47\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:47</a>. <span class=\"greek\">τῆς</span> <span class=\"greek\">πλατείας</span>, pelo meio da rua <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.22.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 22:2</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">μ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">αὐλῆς</span>, no meio do pátio <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.55\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:55a</a>; <span class=\"greek\">τοῦ</span> <span class=\"greek\">τάφου</span> GPt 13:55. <span class=\"greek\">ἐν</span> <span class=\"greek\">μ</span>. <span class=\"greek\">αὐτῆς</span>, no interior dela (da cidade de Jerusalém) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:21</a>; cf. Dg 12:3; MPol 12:1; 12:2(?). <span class=\"greek\">ἐν</span> <span class=\"greek\">μ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θρόνου</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">τεσσάρων</span> <span class=\"greek\">ζῴων</span>, no centro do trono e entre os quatro seres viventes <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.5.6\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 5:6a</a> (com duplo genitivo, também “entre”: Appian, Hann. 14 §60, Bell. Civ. 5, 23 §92; Arrian, Anab. 1, 20, 2; 3, 28, 8 e outros; Lucian, Fugit. 10 <span class=\"greek\">ἐν</span> <span class=\"greek\">μ</span>. <span class=\"greek\">ἀλαζονείας</span> <span class=\"greek\">κ</span>. <span class=\"greek\">φιλοσοφίας</span>). <span class=\"greek\">ἐν</span> <span class=\"greek\">μέσῳ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θρόνου</span>, ao redor (de todos os lados) do trono 4:6 (mas entre o trono e um ponto mais distante: RBrewer, JBL 71, ’52, 227–31).—<span class=\"greek\">ἐν</span> <span class=\"greek\">μέσῳ</span> <span class=\"greek\">ἐκκλησίας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:12</a> (Ps 21:23); cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:22</a>. <span class=\"greek\">κατὰ</span> <span class=\"greek\">μέσον</span> (Jos., Bell. 5, 207; SibOr 3, 802 <span class=\"greek\">κατὰ</span> <span class=\"greek\">μέσσον</span>=“no meio” [do dia]): <span class=\"greek\">κατὰ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">νυκτός</span>, por volta da meia-noite <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:25</a> D; 27:27.</p><p class=\"entry-text\">ⓒ O neutro <span class=\"greek\">μέσον</span> funciona como advérbio (por exemplo, Appian, Bell. Civ. 3, 43 §175 <span class=\"greek\">μ</span>.=entrementes): <span class=\"greek\">ἦν</span> <span class=\"greek\">μέσον</span> <span class=\"greek\">ὡς</span>, ele estava no meio dele, como MPol 15:2; e é usado como preposição com genitivo (B-D-F §215, 3; Rob. 644. Cf. Hdt. 9, 107, 2; Polyb. 8, 25, 1; Epict. 2, 22, 10; LXX, TestSol; TestAbr A 4 p. 80, 31 [Stone p. 8]; JosAs 24:21; Jos., Ant. 6, 65; SibOr 3, 319): <span class=\"greek\">μ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">θαλάσσης</span>, no meio do lago <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:24</a>, variante textual; <span class=\"greek\">μ</span>. <span class=\"greek\">γενεᾶς</span> <span class=\"greek\">σκολιᾶς</span>, no meio de uma geração perversa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:15</a> (cf. Maximus Tyr. 36, 5a <span class=\"greek\">ἐν</span> <span class=\"greek\">μέσῳ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">σιδηρῷ</span> <span class=\"greek\">τούτῳ</span> <span class=\"greek\">γένει</span>).</p><p class=\"entry-text\">② Relativo a uma posição dentro de um grupo, sem enfatizar a posição intermediária: entre, no meio de.</p><p class=\"entry-text\">ⓐ Como adjetivo: <span class=\"greek\">ἐκάθητο</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">Πέτρος</span> <span class=\"greek\">μέσος</span> <span class=\"greek\">αὐτῶν</span>, Pedro estava sentado entre eles <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.55\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:55</a> (o ponto importante não é que fosse o centro das atenções, mas que passava despercebido no grupo; cf. Jos., Ant. 9, 107). <span class=\"greek\">μέσος</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">ἕστηκεν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.26\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:26</a> (Jos., Ant. 14, 23). <span class=\"greek\">τοῦ</span> <span class=\"greek\">πύργου</span> <span class=\"greek\">μέσου</span> Hs 9, 8, 2. <span class=\"greek\">εἶδον</span> … <span class=\"greek\">μέσον</span> <span class=\"greek\">αὐτῶν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">Παῦλον</span> AcPl Ha 11, 14.</p><p class=\"entry-text\">ⓑ Como substantivo neutro, <span class=\"greek\">ἀνὰ</span> <span class=\"greek\">μέσον</span> <span class=\"greek\">τινός</span> (ver <span class=\"greek\">ἀνά</span> 1), entre algo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:25</a>. Com genitivo plural (TestJob 32:6 <span class=\"greek\">ἐν</span> <span class=\"greek\">μέσῳ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">τέκνων</span> <span class=\"greek\">σου</span>), no meio de, entre, em resposta às perguntas “onde?” e “para onde?” (B-D-F §215, 3 apêndice) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:2</a>, 20; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:36</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.46\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:46</a>; 24:36; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:15</a>; 2:22; 6:15 D; 27:21; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.5.6\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 5:6b</a>; cf. 6:6. De relações pessoais estreitas, <span class=\"greek\">ἐν</span> <span class=\"greek\">μέσῳ</span> <span class=\"greek\">ὑμῶν</span>, entre vós = em comunhão convosco <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:27</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:7</a>.—<span class=\"greek\">ἐν</span> <span class=\"greek\">μ</span>. <span class=\"greek\">λύκων</span>, entre lobos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.3\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:3</a>; 2 Cl 5:2.—Com genitivo plural de coisas (Alciphron 3, 24, 3) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 1:13</a>; 2:1. <span class=\"greek\">ἐκ</span> (<span class=\"greek\">τοῦ</span>) <span class=\"greek\">μ</span>., dentre, do meio de (X., An. 1, 5, 14b; resposta oracular em Diod S 9, 3, 2; LXX=<span class=\"hebrew\" dir=\"rtl\">מִתּוֹךְ</span>): <span class=\"greek\">αἴρειν</span> <span class=\"greek\">τι</span> (ou <span class=\"greek\">τινά</span>) <span class=\"greek\">ἐκ</span> (<span class=\"greek\">τοῦ</span>) <span class=\"greek\">μέσου</span> (<span class=\"greek\">τινῶν</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.5.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 5:2</a> (ver <span class=\"greek\">αἴρω</span> 3). <span class=\"greek\">ἁρπάσαι</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">αὐτῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 23:10</a> (ver <span class=\"greek\">ἁρπάζω</span> 2a). <span class=\"greek\">ἀφορίζειν</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">πονηροὺς</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">δικαίων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.49\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:49</a> (ver <span class=\"greek\">ἀφορίζω</span> 1). <span class=\"greek\">γίνεσθαι</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">μ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 2:7</a> (ver <span class=\"greek\">γίνομαι</span> 6b). <span class=\"greek\">ἐξέρχεσθαι</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">αὐτῶν</span>, sair do meio deles <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.33\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:33</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.6.17\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 6:17</a> (cf. Is 52:11). <span class=\"greek\">κύριος</span> <span class=\"greek\">λαμβάνει</span> <span class=\"greek\">ἑαυτῷ</span> <span class=\"greek\">ἔθνος</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">ἐθνῶν</span> 1 Cl 29:3 (cf. Dt 4:34).—B. 864. DELG. M-M. EDNT. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0231-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεσότοιχον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μεσότοιχον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (o substantivo <span class=\"greek\">ὁ</span> <span class=\"greek\">μεσότοιχος</span> [<span class=\"greek\">μέσος</span>, <span class=\"greek\">τοῖχος</span>] = parede divisória em Eratosthenes: Athen. 7, 14, 281d; inscrição de Argos: BCH 33, 1909, 452 n.º 22, 16.—Mas cf. uma inscrição de Dídima: ABA 1911, 56 linha 13 <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">μεσοτοίχου</span>, em que <span class=\"greek\">μ</span>. pode igualmente derivar de <span class=\"greek\">τὸ</span> <span class=\"greek\">μεσότοιχον</span>; este ocorre em Vi. Aesopi W 75 P.; cf. Jos., Ant. 8, 71 <span class=\"greek\">ὁ</span> <span class=\"greek\">μέσος</span> <span class=\"greek\">τοῖχος</span>; em PAmh II, 98, 9 <span class=\"greek\">μέρος</span> <span class=\"greek\">μεσοτύχ</span>(<span class=\"greek\">ων</span>) <span class=\"greek\">οἰκιῶν</span>, o editor sugere a forma adjetiva <span class=\"greek\">μεσοτοίχων</span>), parede divisória; <span class=\"greek\">τὸ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">φραγμοῦ</span>, a barreira constituída pela parede divisória entre nós <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 2:14</a>.—M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0231-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεσουράνημα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μεσουράνημα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> (Posidon.: 87 Fgm. 85 p. 273, 15 Jac.; Manetho, Plut.; Sext. Emp., POxy 235, 13 [século I d.C.]), literalmente, na astronomia, o “meridiano” (“culminação”; <span class=\"greek\">μεσουρανεῖν</span> significa “estar no zênite”, do sol [Aristot., Plut.; escólio a Apollon. Rhod. 1, 450; PGM 4, 2992]): zênite; <span class=\"greek\">ἐν</span> <span class=\"greek\">μεσουρανήματι</span>, no meio do céu <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.8.13\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 8:13</a>; 14:6; 19:17.—M-M.</p></section></article>"};
